","pipeline.js":"// pipeline.js – analyze function

function normalize(text) {
  var s = String(text);
  s = s.normalize('NFKC');
  s = s.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  s = s.toLowerCase();
  s = s.replace(/\s+/g, ' ').trim();
  return s;
}

function tokenize(text) {
  var normalized = normalize(text);
  var tokens = [];
  var matches = normalized.match(/[a-z0-9]+(?:'[a-z0-9]+)*/g);
  if (matches) {
    for (var i = 0; i < matches.length; i++) {
      var token = matches[i];
      if (token !== 'a' && token !== 'the') {
        tokens.push(token);
      }
    }
  }
  return tokens;
}

function analyze(text) {
  var tokens = tokenize(text);
  var count = tokens.length;
  var unique = [];
  var frequencies = {};
  var seen = {};
  for (var i = 0; i < tokens.length; i++) {
    var token = tokens[i];
    if (!seen[token]) {
      seen[token] = true;
      unique.push(token);
      frequencies[token] = 0;
    }
    frequencies[token] = (frequencies[token] || 0) + 1;
  }
  var summary = count + ' tokens; ' + unique.length + ' unique';
  return {
    tokens: tokens,
    count: count,
    unique: unique,
    frequencies: frequencies,
    summary: summary
  };
}
